// ── Generate BAS PDF as a Buffer ──────────────────────────────────────
async function generateBasPdf(data: {
  businessName: string
  abn: string
  period: string
  totalIncome: number
  gstCollected: number
  totalExpenses: number
  gstCredits: number
  netGst: number
  paygWithheld: number
  invoices: Array<{ invoice_number: string; client_name: string; issue_date: string; total_inc_gst: number; total_gst: number }>
  generatedDate: string
}): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ margin: 50, size: 'A4' })
    const chunks: Buffer[] = []
    doc.on('data', (chunk: Buffer) => chunks.push(chunk))
    doc.on('end', () => resolve(Buffer.concat(chunks)))
    doc.on('error', reject)

    const DARK   = '#1C1917'
    const MID    = '#57534E'
    const LIGHT  = '#A09590'
    const RED    = '#C84B2F'
    const BORDER = '#E5DDD5'
    const BG     = '#F5F0E8'

    const pageW  = doc.page.width  - 100
    const fmtN   = (n: number) => `$${Math.abs(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}`

    // ── Header bar ────────────────────────────────────────────────
    doc.rect(50, 50, pageW, 70).fill(DARK)
    doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(16).text(data.businessName, 70, 65)
    doc.fillColor(LIGHT).font('Helvetica').fontSize(10)
      .text(`BAS Summary — ${data.period}`, 70, 87)
      .text(data.abn ? `ABN: ${data.abn}` : '', 70, 102)

    // ── Summary box ───────────────────────────────────────────────
    let y = 140
    doc.rect(50, y, pageW, 160).fill(BG)

    const col1 = 70
    const col2 = 370
    y += 16

    const row = (label: string, value: string, bold = false, color = DARK) => {
      doc.fillColor(MID).font('Helvetica').fontSize(10).text(label, col1, y)
      doc.fillColor(color).font(bold ? 'Helvetica-Bold' : 'Helvetica').fontSize(bold ? 12 : 10)
        .text(value, col2, y, { align: 'right', width: pageW - col2 + 50 })
      y += 20
    }

    row('Total Income (inc. GST)', fmtN(data.totalIncome))
    row('GST Collected on Sales (1A)', fmtN(data.gstCollected))
    y += 4
    doc.moveTo(col1, y).lineTo(col1 + pageW - 20, y).strokeColor(BORDER).lineWidth(0.5).stroke()
    y += 8
    row('Total Expenses (inc. GST)', fmtN(data.totalExpenses))
    row('GST Credits on Purchases (1B)', fmtN(data.gstCredits))
    y += 4
    doc.moveTo(col1, y).lineTo(col1 + pageW - 20, y).strokeColor(BORDER).lineWidth(0.5).stroke()
    y += 8

    const netLabel = data.netGst >= 0 ? 'Net GST Payable to ATO' : 'GST Refund from ATO'
    row(netLabel, fmtN(data.netGst), true, data.netGst >= 0 ? RED : DARK)

    if (data.paygWithheld > 0) {
      y += 4
      doc.moveTo(col1, y).lineTo(col1 + pageW - 20, y).strokeColor(BORDER).lineWidth(0.5).stroke()
      y += 8
      row('PAYG Withholding from Employees (W2)', fmtN(data.paygWithheld))
      const totalPayable = data.netGst + data.paygWithheld
      row('Total Amount Payable to ATO', fmtN(totalPayable), true, RED)
    }

    // ── Invoice list ──────────────────────────────────────────────
    if (data.invoices.length > 0) {
      y += 20
      doc.fillColor(DARK).font('Helvetica-Bold').fontSize(11).text('Invoices', 50, y)
      y += 16

      // Table header
      doc.rect(50, y, pageW, 18).fill(DARK)
      doc.fillColor('#FFFFFF').font('Helvetica-Bold').fontSize(8)
        .text('NUMBER',    70,  y + 5)
        .text('CLIENT',    145, y + 5)
        .text('DATE',      330, y + 5)
        .text('TOTAL',     405, y + 5)
        .text('GST',       470, y + 5)
      y += 18

      data.invoices.forEach((inv, i) => {
        if (i % 2 === 0) doc.rect(50, y, pageW, 18).fill(BG)
        doc.fillColor(MID).font('Helvetica').fontSize(8)
          .text(inv.invoice_number,                70,  y + 5, { width: 70 })
          .text(inv.client_name,                   145, y + 5, { width: 180 })
          .text(inv.issue_date,                    330, y + 5, { width: 70 })
          .text(fmtN(inv.total_inc_gst),           405, y + 5, { width: 60 })
          .text(fmtN(inv.total_gst),               470, y + 5, { width: 60 })
        y += 18
        if (y > doc.page.height - 80) { doc.addPage(); y = 50 }
      })
    }

    // ── Footer ────────────────────────────────────────────────────
    y = doc.page.height - 60
    doc.moveTo(50, y).lineTo(50 + pageW, y).strokeColor(BORDER).lineWidth(0.5).stroke()
    doc.fillColor(LIGHT).font('Helvetica').fontSize(8)
      .text(`Generated by SAB Account AI · sabaccountai.com · ${data.generatedDate}`, 50, y + 10, { align: 'center', width: pageW })

    doc.end()
  })
}

